import{_ as a,o as e,c as i,a5 as r}from"./chunks/framework.a5no_H3L.js";const f=JSON.parse('{"title":"首次生产部署","description":"本页是面向已有 Redis 基础的运维人员的部署操作指南，配置示例以 Redis 7.4.11 为基准。它回答一个问题：如何把 Redis 安全地部署到生产环境，并在上线前确认数据、网络、监控和故障恢复条件。","frontmatter":{},"headers":[],"relativePath":"redis/05-practice/chapter-03-first-production.md","filePath":"redis/05-practice/chapter-03-first-production.md"}'),s={name:"redis/05-practice/chapter-03-first-production.md"};function c(d,t,l,n,p,o){return e(),i("div",null,[...t[0]||(t[0]=[r(`<h1 id="首次生产部署" tabindex="-1" data-src-line="1" data-src-file="redis/05-practice/chapter-03-first-production.md">首次生产部署 <a class="header-anchor" href="#首次生产部署" aria-label="Permalink to &quot;首次生产部署&quot;">​</a></h1><p data-src-line="3" data-src-file="redis/05-practice/chapter-03-first-production.md">本页是面向已有 Redis 基础的运维人员的部署操作指南，配置示例以 Redis 7.4.11 为基准。它回答一个问题：如何把 Redis 安全地部署到生产环境，并在上线前确认数据、网络、监控和故障恢复条件。</p><h2 id="明确部署前提" tabindex="-1" data-src-line="5" data-src-file="redis/05-practice/chapter-03-first-production.md">明确部署前提 <a class="header-anchor" href="#明确部署前提" aria-label="Permalink to &quot;明确部署前提&quot;">​</a></h2><p data-src-line="7" data-src-file="redis/05-practice/chapter-03-first-production.md">开始配置前，先记录以下输入：</p><ul data-src-line="9" data-src-file="redis/05-practice/chapter-03-first-production.md"><li data-src-line="9" data-src-file="redis/05-practice/chapter-03-first-production.md">数据的恢复点目标（RPO）和恢复时间目标（RTO）。</li><li data-src-line="10" data-src-file="redis/05-practice/chapter-03-first-production.md">预计数据量、峰值 QPS、平均值大小和大 Key 上限。</li><li data-src-line="11" data-src-file="redis/05-practice/chapter-03-first-production.md">客户端只能从哪些网段访问 Redis。</li><li data-src-line="12" data-src-file="redis/05-practice/chapter-03-first-production.md">数据是否允许被淘汰，以及故障转移时最多能接受多少已确认写入丢失。</li><li data-src-line="13" data-src-file="redis/05-practice/chapter-03-first-production.md">是否需要跨机房部署，以及网络分区时允许哪一侧继续写入。</li></ul><p data-src-line="15" data-src-file="redis/05-practice/chapter-03-first-production.md">这些输入决定拓扑、持久化和淘汰策略。没有这些输入时，不应直接套用“推荐配置”。</p><h2 id="限制网络访问" tabindex="-1" data-src-line="17" data-src-file="redis/05-practice/chapter-03-first-production.md">限制网络访问 <a class="header-anchor" href="#限制网络访问" aria-label="Permalink to &quot;限制网络访问&quot;">​</a></h2><p data-src-line="19" data-src-file="redis/05-practice/chapter-03-first-production.md">Redis 端口只允许受信任的应用服务器访问：</p><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 绑定到实例的私网地址，不要绑定到公网地址</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bind 10.0.0.21</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port 6379</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">protected-mode yes</span></span></code></pre></div><p data-src-line="28" data-src-file="redis/05-practice/chapter-03-first-production.md">同时完成以下检查：</p><ol data-src-line="30" data-src-file="redis/05-practice/chapter-03-first-production.md"><li data-src-line="30" data-src-file="redis/05-practice/chapter-03-first-production.md">在主机防火墙或云安全组中，只允许应用网段访问 <code>6379</code>。</li><li data-src-line="31" data-src-file="redis/05-practice/chapter-03-first-production.md">不要把 Redis 端口映射到公网，也不要把端口暴露给办公网或不可信容器网络。</li><li data-src-line="32" data-src-file="redis/05-practice/chapter-03-first-production.md">使用 Redis ACL 创建按应用分离、只授必要命令和 Key 模式的用户。</li><li data-src-line="33" data-src-file="redis/05-practice/chapter-03-first-production.md">Redis 与客户端跨越不可信网络时启用 TLS；密码通过密钥管理系统注入，不写入仓库。</li><li data-src-line="34" data-src-file="redis/05-practice/chapter-03-first-production.md">为管理命令设置审计和变更流程，不把 <code>rename-command</code> 当作认证措施。</li></ol><p data-src-line="36" data-src-file="redis/05-practice/chapter-03-first-production.md">官方<a href="https://redis.io/docs/latest/operate/oss_and_stack/management/security/" target="_blank" rel="noreferrer">安全文档</a>要求 Redis 端口只能被受信任客户端访问，并把 ACL 作为 Redis 6 之后推荐的认证方式。网络、ACL、TLS 和轮换步骤见<a href="./../04-operations/chapter-02-security-access.html">安全与访问控制</a>。</p><h2 id="选择部署拓扑" tabindex="-1" data-src-line="38" data-src-file="redis/05-practice/chapter-03-first-production.md">选择部署拓扑 <a class="header-anchor" href="#选择部署拓扑" aria-label="Permalink to &quot;选择部署拓扑&quot;">​</a></h2><p data-src-line="40" data-src-file="redis/05-practice/chapter-03-first-production.md">拓扑不能单独保证“不丢数据”。先按下表选择：</p><table tabindex="0"><thead data-src-line="42" data-src-file="redis/05-practice/chapter-03-first-production.md"><tr data-src-line="42" data-src-file="redis/05-practice/chapter-03-first-production.md"><th style="text-align:left;">主要约束</th><th style="text-align:left;">可考虑的拓扑</th><th style="text-align:left;">仍需处理的风险</th></tr></thead><tbody data-src-line="44" data-src-file="redis/05-practice/chapter-03-first-production.md"><tr data-src-line="44" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">数据量可放入单实例，需要自动故障转移</td><td style="text-align:left;">主从复制 + Sentinel</td><td style="text-align:left;">异步复制可能丢失故障前未复制的写入</td></tr><tr data-src-line="45" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">数据量或吞吐超过单实例</td><td style="text-align:left;">Redis Cluster</td><td style="text-align:left;">跨槽限制、迁移风险和分区写安全</td></tr><tr data-src-line="46" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">只有单实例且可接受重启后重建</td><td style="text-align:left;">单实例</td><td style="text-align:left;">没有故障转移，单点可用性</td></tr><tr data-src-line="47" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">需要分片但不要求 Redis 原生高可用</td><td style="text-align:left;">客户端分片或代理</td><td style="text-align:left;">需要自行处理拓扑、重试和故障转移</td></tr></tbody></table><p data-src-line="49" data-src-file="redis/05-practice/chapter-03-first-production.md">Sentinel 和 Redis Cluster 默认都使用异步复制，参见官方<a href="https://redis.io/docs/latest/operate/oss_and_stack/management/replication/" target="_blank" rel="noreferrer">复制说明</a>和 <a href="https://redis.io/docs/latest/develop/reference/cluster-spec/" target="_blank" rel="noreferrer">Cluster 规范</a>。Cluster 不等于“不丢数据”，Sentinel 也不等于“一定丢数据”；两者都需要根据 RPO 配置持久化、副本和写入保护。</p><h2 id="配置内存和淘汰" tabindex="-1" data-src-line="51" data-src-file="redis/05-practice/chapter-03-first-production.md">配置内存和淘汰 <a class="header-anchor" href="#配置内存和淘汰" aria-label="Permalink to &quot;配置内存和淘汰&quot;">​</a></h2><p data-src-line="53" data-src-file="redis/05-practice/chapter-03-first-production.md">先计算可用内存，再设置上限：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Redis 可用内存 ≤ 容器/主机可用内存 - 操作系统和监控开销 - fork/COW 预留</span></span></code></pre></div><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 示例：16 GiB 主机，先预留系统、监控和 fork 空间</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmemory 10gb</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmemory-policy noeviction</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">maxmemory-samples 10</span></span></code></pre></div><p data-src-line="66" data-src-file="redis/05-practice/chapter-03-first-production.md"><code>noeviction</code> 适合不能主动丢弃数据的实例：达到上限后写入会失败，必须配套告警和扩容。只有可重建的缓存才使用 <code>allkeys-lru</code> 或 <code>allkeys-lfu</code>；不要对主数据使用会淘汰全部 Key 的策略。</p><h2 id="配置持久化" tabindex="-1" data-src-line="68" data-src-file="redis/05-practice/chapter-03-first-production.md">配置持久化 <a class="header-anchor" href="#配置持久化" aria-label="Permalink to &quot;配置持久化&quot;">​</a></h2><p data-src-line="70" data-src-file="redis/05-practice/chapter-03-first-production.md">按 RPO 选择持久化，而不是默认照抄：</p><table tabindex="0"><thead data-src-line="72" data-src-file="redis/05-practice/chapter-03-first-production.md"><tr data-src-line="72" data-src-file="redis/05-practice/chapter-03-first-production.md"><th style="text-align:left;">RPO 要求</th><th style="text-align:left;">起点配置</th><th style="text-align:left;">需要验证</th></tr></thead><tbody data-src-line="74" data-src-file="redis/05-practice/chapter-03-first-production.md"><tr data-src-line="74" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">可接受最近数分钟数据丢失</td><td style="text-align:left;">RDB 或从节点持久化</td><td style="text-align:left;">快照窗口、恢复时间和备份保留</td></tr><tr data-src-line="75" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">需要较低的命令级丢失窗口</td><td style="text-align:left;">AOF <code>everysec</code></td><td style="text-align:left;">磁盘吞吐、fsync 延迟和恢复时间</td></tr><tr data-src-line="76" data-src-file="redis/05-practice/chapter-03-first-production.md"><td style="text-align:left;">同时需要快速恢复和较细恢复点</td><td style="text-align:left;">RDB + AOF</td><td style="text-align:left;">fork、磁盘容量和 AOF 重写影响</td></tr></tbody></table><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appendonly yes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appendfsync everysec</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto-aof-rewrite-percentage 100</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auto-aof-rewrite-min-size 256mb</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">save 3600 1 300 100 60 10000</span></span></code></pre></div><p data-src-line="86" data-src-file="redis/05-practice/chapter-03-first-production.md"><code>everysec</code> 允许故障时丢失约一秒窗口的数据。<code>always</code> 提供更细的持久化保证，但会显著增加写延迟；是否使用必须通过目标磁盘和真实负载验证。把持久化转化为可执行流程见<a href="./../04-operations/chapter-03-backup-recovery.html">备份、恢复与升级</a>。</p><h2 id="配置连接与慢日志" tabindex="-1" data-src-line="88" data-src-file="redis/05-practice/chapter-03-first-production.md">配置连接与慢日志 <a class="header-anchor" href="#配置连接与慢日志" aria-label="Permalink to &quot;配置连接与慢日志&quot;">​</a></h2><div class="language-conf vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">conf</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 0 表示不主动断开空闲连接；不要为了“安全”盲目设置服务端超时</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout 0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tcp-keepalive 300</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">slowlog-log-slower-than 10000</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">slowlog-max-len 128</span></span></code></pre></div><p data-src-line="99" data-src-file="redis/05-practice/chapter-03-first-production.md">客户端必须配置连接池上限、连接/读取超时、指数退避和重试上限。<code>timeout</code> 会主动断开空闲客户端，可能影响长连接或低频任务，应根据客户端行为决定。</p><h2 id="上线前验证" tabindex="-1" data-src-line="101" data-src-file="redis/05-practice/chapter-03-first-production.md">上线前验证 <a class="header-anchor" href="#上线前验证" aria-label="Permalink to &quot;上线前验证&quot;">​</a></h2><ul data-src-line="103" data-src-file="redis/05-practice/chapter-03-first-production.md"><li data-src-line="103" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] Redis 只监听私网或回环地址，公网和不可信网段无法连接。</li><li data-src-line="104" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] ACL 用户按应用隔离，凭据通过环境变量或密钥系统注入。</li><li data-src-line="105" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] <code>maxmemory</code> 与数据增长、淘汰策略和告警阈值一致。</li><li data-src-line="106" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] RDB、AOF 和备份均完成一次恢复演练。</li><li data-src-line="107" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] 主从复制延迟、复制偏移和故障转移经过演练。</li><li data-src-line="108" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] 客户端连接池、超时和重试不会在故障时放大流量。</li><li data-src-line="109" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] 大 Key、热 Key、慢命令和内存增长已有检测规则。</li><li data-src-line="110" data-src-file="redis/05-practice/chapter-03-first-production.md">[ ] 已定义 Redis 不可用时应用的降级或只读行为。</li></ul><h2 id="接入监控" tabindex="-1" data-src-line="112" data-src-file="redis/05-practice/chapter-03-first-production.md">接入监控 <a class="header-anchor" href="#接入监控" aria-label="Permalink to &quot;接入监控&quot;">​</a></h2><p data-src-line="114" data-src-file="redis/05-practice/chapter-03-first-production.md">至少采集以下指标，并按业务设置告警：</p><ul data-src-line="116" data-src-file="redis/05-practice/chapter-03-first-production.md"><li data-src-line="116" data-src-file="redis/05-practice/chapter-03-first-production.md">内存：<code>used_memory</code>、<code>used_memory_rss</code>、碎片率、淘汰次数。</li><li data-src-line="117" data-src-file="redis/05-practice/chapter-03-first-production.md">延迟：命令延迟分位数、<code>SLOWLOG</code>、<code>latest_fork_usec</code>。</li><li data-src-line="118" data-src-file="redis/05-practice/chapter-03-first-production.md">流量：QPS、网络入出带宽、客户端连接数。</li><li data-src-line="119" data-src-file="redis/05-practice/chapter-03-first-production.md">数据：命中率、Key 数量、过期数量、主从复制偏移差。</li><li data-src-line="120" data-src-file="redis/05-practice/chapter-03-first-production.md">持久化：RDB 最后保存时间、AOF 状态、磁盘剩余空间。</li><li data-src-line="121" data-src-file="redis/05-practice/chapter-03-first-production.md">高可用：Sentinel 状态、Cluster 节点状态、故障转移次数。</li></ul><p data-src-line="123" data-src-file="redis/05-practice/chapter-03-first-production.md">上线后先观察一个完整业务周期，再逐步提高流量。监控指标的阈值应来自基线，而不是直接复制示例值。</p>`,35)])])}const u=a(s,[["render",c]]);export{f as __pageData,u as default};
